formulas.expression:
IF(  
    TEXT({!recordId.Owner:User.Team__c}) = "LawCareers.Net", "LCN",  
        IF(  
            TEXT({!recordId.Owner:User.Team__c}) = "Expert Insight - Lexology Panoramic", "Paid_Content",  
            IF(  
                TEXT({!recordId.Owner:User.Team__c}) = "Expert Insight - GXRs", "Paid_Content",  
                IF(  
                    TEXT({!recordId.Owner:User.Team__c}) = "Expert Insight - Lexology In-Depth", "Paid_Content",  
                    IF(  
                        TEXT({!recordId.Owner:User.Team__c}) = "Lex ILO", "Subscriptions_ILO",  
                        IF(  
                            TEXT({!recordId.Owner:User.Team__c}) = "Lexology Intelligence", "Lexology_Intelligence",  
                            IF(  
                                TEXT({!recordId.Owner:User.Team__c}) = "Performance Data - GxRs", "Performance_Data_GXRs",  
                                    "" 
                                )  
                            )  
                        )  
                    )  
                )  
            )  
        )
